SELECT task_id AS taskId, COUNT(DISTINCT invoke_id) AS batchCnt, COUNT(*) AS totalCnt, SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END) AS deliveredCnt, SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END) AS unsentCnt, SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) AS failFriendCnt, SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END) AS failOtherCnt FROM wx_mass_target_log WHERE task_id IN
#{id}
GROUP BY task_id
